    .wdata(PWDATA[MDW-1:0]), .data_size(cfg[3:0]),
    .stop_bits_count(cfg[4]), .parity_type(cfg[7:5]),
    .txfifotr(tx_threshold), .rxfifotr(rx_threshold), .match_data(match_data),
    .timeout_bits(cfg[13:8]), .loopback_en(ctrl[3]),
    .glitch_filter_en(ctrl[4]), .tx_fifo_flush(tx_flush), .rx_fifo_flush(rx_flush),
    .tx_empty(tx_empty), .tx_full(tx_full), .tx_level(tx_level), .tx_level_below(tx_below),
    .rdata(rdata), .rx_empty(rx_empty), .rx_full(rx_full), .rx_level(rx_level),
