      A_PR: PRDATA = {16'b0,prescaler};
      A_CTRL: PRDATA = {27'b0,ctrl};
      A_CFG: PRDATA = {18'b0,cfg};
      A_MATCH: PRDATA = {23'b0,match_data};
      A_RXLEV: PRDATA = {28'b0,rx_level};
      A_RXTH: PRDATA = {28'b0,rx_threshold};
      A_RXFL: PRDATA = {31'b0,rx_flush};
      A_TXLEV: PRDATA = {28'b0,tx_level};
      A_TXTH: PRDATA = {28'b0,tx_threshold};
      A_TXFL: PRDATA = {31'b0,tx_flush};
      A_IM: PRDATA = {22'b0,im};
      A_MIS: PRDATA = {22'b0,(ris & im)};
      A_RIS: PRDATA = {22'b0,ris};
      A_GCLK: PRDATA = {31'b0,gclk};
    endcase
  end
  assign PREADY = 1'b1;
  assign IRQ = |(ris & im);
endmodule
