      A_RXTH:    PRDATA = {28'b0,rxth_reg};
      A_RXFL:    PRDATA = 0;
      A_TXL:     PRDATA = {{(32-FAW){1'b0}},tx_level};
      A_TXTH:    PRDATA = {28'b0,txth_reg};
      A_TXFL:    PRDATA = 0;
      A_IM:      PRDATA = {22'b0,im_reg};
      A_MIS:     PRDATA = {22'b0,(ris_reg & im_reg)};
      A_RIS:     PRDATA = {22'b0,ris_reg};
      A_GCLK:    PRDATA = {31'b0,gclk_reg};
      default:   PRDATA = 32'hdeadbeef;
    endcase
  end

  wire [9:0] ris_set = {timeout_f, overrun_f, pe_f, fe_f, match_f, break_f,
                         rx_above, tx_below, rx_full, tx_empty};
  wire [9:0] ic_write = (wr_x && addr==A_IC) ? PWDATA[9:0] : 10'b0;
  always @(posedge PCLK or negedge PRESETn) begin
    if (!PRESETn) begin
      pr_reg<=0; ctrl_reg<=0; cfg_reg<=14'h3f08; match_reg<=0;
      rxth_reg<=0; txth_reg<=0; im_reg<=0; ris_reg<=0; gclk_reg<=0;
    end else begin
      if (wr_x && addr==A_PR) pr_reg <= PWDATA[15:0];
      if (wr_x && addr==A_CTRL) ctrl_reg <= PWDATA[4:0];
      if (wr_x && addr==A_CFG) cfg_reg <= PWDATA[13:0];
      if (wr_x && addr==A_MATCH) match_reg <= PWDATA[8:0];
      if (wr_x && addr==A_RXTH) rxth_reg <= PWDATA[3:0];
      if (wr_x && addr==A_TXTH) txth_reg <= PWDATA[3:0];
      if (wr_x && addr==A_IM) im_reg <= PWDATA[9:0];
      if (wr_x && addr==A_GCLK) gclk_reg <= PWDATA[0];
      ris_reg <= (ris_reg | ris_set) & ~ic_write;
    end
  end
  assign IRQ = |(ris_reg & im_reg);
endmodule
